/**
 * The simulated gasoline terminal, as declared in the Verum public reference.
 * facility.json is generated by scripts/extract-facility.py (see README.md in this folder).
 * GET /api/facility overrides it when a backend provides one.
 */
import snapshot from './facility.json'

export type AssetKind = 'tank' | 'pump' | 'isolation_valve' | 'pipe' | 'pressure_transmitter' | (string & {})

export interface FacilityAsset {
  asset_id: string
  kind: AssetKind
  label: string
  /** Asset or graph node ids this asset is directly connected to. */
  connects_to: string[]
  /** Schematic position [x, y, z] (not to scale). */
  position_hint?: number[] | null
  area?: string
  graph_role?: 'edge' | 'node' | 'port_owner' | 'mounted_instrument'
  from_node?: string
  to_node?: string
  ports?: string[]
  mounted_on?: { element_id: string | null; element_type: 'edge' | 'node'; record_type?: string | null }
  route_ids?: string[]
  declared_specs?: boolean
  specs?: Record<string, unknown>
}

export interface FacilityNode {
  node_id: string
  asset_id: string | null
  port_of: string | null
  role: 'asset' | 'port' | 'junction'
  position_hint?: number[] | null
}

export interface FacilitySensor {
  tag_id: string
  unit: string
  /** null when the source does not tie the tag to an asset (see `association`). */
  asset_id: string | null
  label?: string
  sampling_kind?: string
  measured_element?: { record_type: string | null; element_id: string | null; field: string | null }
  association?: string | null
}

export interface CatalogAction {
  action_id: string
  name: string
  target_kind: string
  targets: string
  preconditions: string[]
  cost_usd: number | null
  duration_min: number | null
}

export interface Facility {
  assets: FacilityAsset[]
  sensors: FacilitySensor[]
  nodes?: FacilityNode[]
  inspection_catalog?: CatalogAction[]
  layout?: { kind: string; note: string }
  source?: { verum_commit: string; data_release: string; simulated: boolean }
  /** where this facility came from in the UI */
  origin?: 'snapshot' | 'api'
}

export const STATIC_FACILITY: Facility = { ...(snapshot as unknown as Facility), origin: 'snapshot' }

export const KIND_LABEL: Record<string, string> = {
  tank: 'Tank',
  pump: 'Pump',
  isolation_valve: 'Isolation valve',
  pipe: 'Pipe segment',
  pressure_transmitter: 'Pressure transmitter',
}
export const kindLabel = (k: string) => KIND_LABEL[k] ?? k.replace(/_/g, ' ')

/** Display order of kinds: main equipment first. Unknown kinds go last, never dropped. */
export const KIND_ORDER = ['tank', 'pump', 'isolation_valve', 'pressure_transmitter', 'pipe']
export function kindRank(k: string): number {
  const i = KIND_ORDER.indexOf(k)
  return i === -1 ? KIND_ORDER.length : i
}

export function assetById(f: Facility, id: string): FacilityAsset | undefined {
  return f.assets.find((a) => a.asset_id === id)
}

export function sensorsForAsset(f: Facility, assetId: string): FacilitySensor[] {
  return f.sensors.filter((s) => s.asset_id === assetId)
}

/** Ids referenced by a run that the facility does not contain (shown as a warning badge). */
export function unknownIds(f: Facility, ids: Iterable<string>): string[] {
  const known = new Set<string>([...f.assets.map((a) => a.asset_id), ...f.sensors.map((s) => s.tag_id)])
  const out: string[] = []
  for (const id of ids) if (!known.has(id) && !out.includes(id)) out.push(id)
  return out
}

/** The asset immediately downstream of `id` along the declared flow (pipes leaving it). */
export function downstreamPipes(f: Facility, id: string): FacilityAsset[] {
  const a = assetById(f, id)
  if (!a) return []
  if (a.kind === 'pressure_transmitter' && a.mounted_on?.element_type === 'edge' && a.mounted_on.element_id) {
    const host = assetById(f, a.mounted_on.element_id)
    return host ? [host] : []
  }
  return f.assets.filter((p) => p.graph_role === 'edge' && p.from_node && (p.from_node === id || p.from_node.startsWith(`${id}:`)))
}

/**
 * Ids that GET /api/facility lists and the static layout snapshot does not, and the other way round.
 * The service gives no drawing coordinates, so the layout always comes from the snapshot; this is how a difference shows.
 * Tags the service withholds are not compared.
 */
export function serviceMismatch(api: { assets: { asset_id: string }[]; tags: { tag_id: string; status?: string }[] }, snapshot: Facility = STATIC_FACILITY): string[] {
  const a = new Set([...api.assets.map((x) => x.asset_id), ...api.tags.filter((t) => t.status !== 'withheld').map((x) => x.tag_id)])
  const b = new Set([...snapshot.assets.map((x) => x.asset_id), ...snapshot.sensors.map((x) => x.tag_id)])
  return [...[...a].filter((x) => !b.has(x)), ...[...b].filter((x) => !a.has(x))]
}
